int shared_counter = 0;

// Atomicity Violation: Read-Modify-Write is interrupted.
// If two threads call this simultaneously, expected result 2, actual result 1.
void* increment_unsafe(void* arg) {
    // 1. READ (Load value into CPU register/local variable)
    int temp = shared_counter;

    // *** CONTEXT SWITCH/INTERRUPTION HERE ***

    // 2. MODIFY (Compute new value)
    temp = temp + 1;

    // 3. WRITE (Store computed value back)
    shared_counter = temp;
    return NULL;
}

// Fix: Requires synchronization (e.g., mutex lock around the three steps)
// or use of atomic types.
